const body = $json.body || {};
const prompt = String(body.prompt || '');
const viewSettings = body.viewSettings && typeof body.viewSettings === 'object' ? body.viewSettings : {};
const dataContext = String(body.dataContext || '');
const allowedOps = Array.isArray(body.allowedOps) ? body.allowedOps : [];
const system = [
  'You are the O2O sales copilot for a Tops Thailand sales dashboard (streams: QC quick commerce, PS personal shopper, TOL Tops Online).',
  'Answer using ONLY the provided data context, unless the question is general knowledge.',
  'Always respond with STRICT JSON only — no markdown, no code fences — matching exactly:',
  '{"reply": string, "viewSettings": object}',
  'viewSettings may contain ONLY these optional keys, and only when the user clearly asks for the change:',
  '- "channel": array, a non-empty subset of ["O2O","QC","PS","TOL"]',
  '- "ops": string, one of the allowed Head of Ops values (or "" for all)',
  '- "from": string "YYYY-MM-DD"',
  '- "to": string "YYYY-MM-DD"',
  '- "trendGranularity": "month" | "week" | "day"',
  '- "showLabels": boolean',
  'Never invent extra keys. If the request is general conversation, set viewSettings to {}.',
  'Reply in the language of the user message. Be concise and concrete, citing the numbers you were given.'
].join('\n');
const userContent = [
  'Current view settings: ' + JSON.stringify(viewSettings),
  'Allowed Head of Ops values: ' + JSON.stringify(allowedOps),
  'Data context: ' + (dataContext || '(none provided)'),
  '',
  'User request: ' + prompt
].join('\n');
return [{ json: { messages: [
  { role: 'system', content: system },
  { role: 'user', content: userContent }
] } }];

const payload = $json;
let content = '';
try { content = payload.choices[0].message.content || ''; } catch (error) {}
let reply = '';
let viewSettings = {};
try {
  const cleaned = String(content).replace(/```json/gi, '').replace(/```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  const parsed = JSON.parse(start >= 0 && end > start ? cleaned.slice(start, end + 1) : cleaned);
  if (typeof parsed.reply === 'string') reply = parsed.reply;
  if (parsed.viewSettings && typeof parsed.viewSettings === 'object' && !Array.isArray(parsed.viewSettings)) {
    const allowed = ['channel', 'ops', 'from', 'to', 'trendGranularity', 'showLabels'];
    for (const key of Object.keys(parsed.viewSettings)) {
      if (!allowed.includes(key)) delete parsed.viewSettings[key];
    }
    viewSettings = parsed.viewSettings;
  }
} catch (error) {}
if (!reply) reply = 'The copilot model returned an unreadable answer — please rephrase or try again later.';
return [{ json: { reply, viewSettings } }];
